using System.Net.Http.Json;

public class RabbitHealthProbe
{
    private readonly HttpClient _http = new();

    public async Task<bool> IsHealthyAsync(string managementUrl, string queueName)
    {
        var response = await _http.GetFromJsonAsync<QueueInfo>($"{managementUrl}/api/queues/%2F/{queueName}");
        return response is
        {
            Messages: < 1000,
            Consumers: > 0
        };
    }

    private record QueueInfo(int Messages, int Consumers);
}
